import json

def mcp_call(payload):
    """Send JSON-RPC payload to the MCP server via curl, return parsed result."""
    url = "http://127.0.0.1:40573/mcp/e261b05542aa3b2af42bd43df48a77ad"
    cmd = (
        'curl -s -X POST ' + url +
        ' -H "Content-Type: application/json" -H "Accept: application/json, text/event-stream" '
        '-d ' + json.dumps(json.dumps(payload))
    )
    raw = tools.run_command(command=cmd)
    # raw is a string like '{"jsonrpc":"2.0",...}' possibly wrapped
    for line in raw.splitlines():
        if line.startswith('{'):
            return json.loads(line)
    return raw

